using System;using System.Drawing;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Threading;using System.Windows.Forms;
namespace Frociart.Tests {internal static class IoBlockTests {
 static int checks;static BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;static string folder;
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);checks++;Console.WriteLine("PASS "+name);}
 static object Call(object obj,string name,params object[] args){return obj.GetType().GetMethods(F).First(m=>m.Name==name&&m.GetParameters().Length==args.Length).Invoke(obj,args);}
 static T Get<T>(object obj,string name){return(T)obj.GetType().GetField(name,F).GetValue(obj);}
 static void Pump(int ms=30){var end=DateTime.UtcNow.AddMilliseconds(ms);do{Application.DoEvents();Thread.Sleep(3);}while(DateTime.UtcNow<end);}
 static IEnumerable<Control> Walk(Control root){yield return root;foreach(Control c in root.Controls)foreach(var n in Walk(c))yield return n;}
 static string Bytes(Diagram d){return Convert.ToBase64String(DiagramIO.EncodeDocument(d));}
 static Diagram Fixture(){var d=new Diagram();d.Nodes.AddRange(new[]{new FlowNode{Id="s",Kind=NodeKind.Start,Text="Inizio",X=100,Y=20},new FlowNode{Id="p",Kind=NodeKind.Process,Text="x = 2",X=76,Y=220},new FlowNode{Id="e",Kind=NodeKind.End,Text="Fine",X=100,Y=530}});d.Edges.AddRange(new[]{new FlowEdge{Id="sp",From="s",To="p"},new FlowEdge{Id="pe",From="p",To="e"}});return d;}
 static Point At(FlowCanvas c,float x,float y){return Point.Round(c.WorldToClient(new PointF(x,y)));}
 static void Reset(MainForm f){f.SetDocument(Fixture(),null,false);f.Canvas.SnapToGrid=false;f.Canvas.FitToView();Pump();}
 static void Shot(MainForm f,string name){Pump(400);using(var bitmap=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(bitmap,new Rectangle(Point.Empty,f.Size));bitmap.Save(Path.Combine(folder,name+".png"));}}
 [STAThread]static int Main(){try{Application.EnableVisualStyles();Ui.SetSeparateIo(false,false);UiMotion.SetEnabled(true);folder=Path.Combine(Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location),"io-commands");Directory.CreateDirectory(folder);
 foreach(var value in new[]{"leggi x"," LEGGI\tx ","stampa x","StAmPa \"leggi x\"","scrivi x","stampa_total","\"stampa x\""}){var n=new FlowNode{Kind=NodeKind.Input};IoInstruction.Apply(n,value);Check(n.Kind==(value.TrimStart().StartsWith("stampa ",StringComparison.OrdinalIgnoreCase)||value.StartsWith("StAmPa")||value.StartsWith("scrivi")?NodeKind.Output:NodeKind.Input),"Command boundary and casing: "+value);}
 var process=new FlowNode{Kind=NodeKind.Process};IoInstruction.Apply(process,"stampa = 3");Check(process.Kind==NodeKind.Process&&process.Text=="stampa = 3","Process assignments are not reinterpreted");
 using(var f=new MainForm(null,true)){f.ShowInTaskbar=false;f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-3000,-2500);f.Size=new Size(1420,1000);f.Show();f.EnterEditor();Pump();
 for(int mode=0;mode<2;mode++){
 bool separate=mode==1;var toggle=Walk(f).OfType<CheckBox>().Single(box=>box.Name=="SeparateIo");if(toggle.Checked!=separate){toggle.Checked=separate;Pump(350);}var palette=Walk(f).OfType<BlockButton>().ToArray();Check(palette.Length==(separate?6:5),"Palette count in mode "+separate);Check(palette.Count(b=>b.Kind==NodeKind.Output)==(separate?1:0),"Output tile follows mode");
 foreach(var dark in new[]{false,true}){Ui.SetDarkMode(dark,false);Check(Ui.KindColor(NodeKind.Input)!=Ui.KindColor(NodeKind.Output),"Read/print have distinct colors in theme "+dark);}
 Reset(f);palette.Single(b=>b.Kind==NodeKind.Input).PerformClick();Pump();Check(f.Document.Nodes.Count==4,"One click inserts without extra chooser");var node=f.Document.Nodes.Last();var id=node.Id;f.Canvas.SelectNode(id);var expression=Get<TextBox>(f,"expression");Check(expression.Text.StartsWith("leggi "),"Editor exposes command");string original=Bytes(f.Document);
 expression.Text="stampa \"Ciao!\"";Pump();Check(node.Kind==NodeKind.Input&&node.Text!="\"Ciao!\"","Preview leaves committed operation intact");Check(IoInstruction.VisualKind(node)==NodeKind.Output,"Preview detects purple print");f.CommitInspector();Check(node.Kind==NodeKind.Output&&node.Text=="\"Ciao!\"","Apply switches operation and strips keyword");Check(!((bool)Call(f,"InspectorHasChanges")),"Applied command has no phantom dirty state");Call(f,"Undo");Check(Bytes(f.Document)==original,"One undo restores original kind, operand and layout");Call(f,"Redo");node=f.Document.Nodes.Single(n=>n.Id==id);Check(node.Kind==NodeKind.Output,"Redo restores print");f.Canvas.SelectNode(id);expression=Get<TextBox>(f,"expression");expression.Text="leggi risposta";f.CommitInspector();Check(node.Kind==NodeKind.Input&&node.Text=="risposta","Existing output becomes input from command");
 Reset(f);string before=Bytes(f.Document);f.Canvas.BeginConnect("p","next");Call(f.Canvas,"ShowBlockPickerAt",At(f.Canvas,182,420),new PointF(182,420),false);Pump(150);var picker=Get<BlockPicker>(f.Canvas,"_blockPicker");picker.Items.Cast<ToolStripItem>().Single(i=>i.Text==(separate?"Input":"Input / Output")).PerformClick();Pump();node=f.Document.Nodes.Last();Check(f.Document.Edges.Any(e=>e.From=="p"&&e.To==node.Id)&&f.Document.Edges.Any(e=>e.From==node.Id&&e.To=="e"),"Connection insertion retains both ends");Call(f,"Undo");Check(Bytes(f.Document)==before,"Connected insertion undo exact");
 Reset(f);before=Bytes(f.Document);var c=f.Canvas;var screen=c.PointToScreen(At(c,182,440));var ev=new DragEventArgs(new DataObject(new FlowCanvas.PaletteBlock(separate?NodeKind.Output:NodeKind.Input,!separate)),1,screen.X,screen.Y,DragDropEffects.Copy,DragDropEffects.None);Call(c,"OnDragEnter",ev);Pump(160);Check(Get<bool>(c,"insertReady"),"Palette drag targets line");Call(c,"OnDragDrop",ev);Pump();node=f.Document.Nodes.Last();Check(node.Kind==(separate?NodeKind.Output:NodeKind.Input),"Drop role is correct without chooser");Check(f.Document.Edges.Any(e=>e.From=="p"&&e.To==node.Id)&&f.Document.Edges.Any(e=>e.From==node.Id&&e.To=="e"),"Drop splits only targeted line");Call(f,"Undo");Check(Bytes(f.Document)==before,"Drop and layout undo together");
 var d=FlowPseudocode.Decode("LEGGI x\nSTAMPA x");f.SetDocument(d,null,false);Pump();before=Bytes(d);toggle=Walk(f).OfType<CheckBox>().Single(t=>t.Name=="SeparateIo");toggle.Checked=!separate;Check(Bytes(d)==before,"Mode change preserves contents, coordinates and connections");Pump(45);Check(FlowTransitions.Active>0||!UiMotion.Enabled,"Mode transition has intermediate frames");Pump(500);toggle=Walk(f).OfType<CheckBox>().Single(t=>t.Name=="SeparateIo");toggle.Checked=separate;Shot(f,separate?"separate":"unified");Check(Bytes(d)==before,"Both mode directions preserve exact graph");
 }
 var round=FlowPseudocode.Decode("leggi x\nstampa x");string text=FlowPseudocode.Encode(round);Check(text.Contains("LEGGI x")&&text.Contains("STAMPA x")&&!text.Contains("SCRIVI"),"Pseudocode uses LEGGI and STAMPA");var engine=new Interpreter(round);for(int i=0;i<10&&engine.State!=RuntimeState.Completed;i++){if(engine.State==RuntimeState.WaitingForInput)engine.ProvideInput("7");else engine.Step();}Check(engine.State==RuntimeState.Completed&&engine.Output.Single()=="7","Read/print execute correctly");f.SetDocument(new Diagram(),null,false);f.Close();}
 Console.WriteLine("IO_COMMAND_PASS checks="+checks);return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}}

